import{_ as a,c as t,o as r,ax as s}from"./chunks/framework.DHqKNX4U.js";const m=JSON.parse('{"title":"Connecting a JMAP Mailbox","description":"","frontmatter":{},"headers":[],"relativePath":"user-guides/email-providers/jmap.md","filePath":"user-guides/email-providers/jmap.md"}'),o={name:"user-guides/email-providers/jmap.md"};function i(n,e,l,h,d,c){return r(),t("div",null,e[0]||(e[0]=[s('<h1 id="connecting-a-jmap-mailbox" tabindex="-1">Connecting a JMAP Mailbox <a class="header-anchor" href="#connecting-a-jmap-mailbox" aria-label="Permalink to &quot;Connecting a JMAP Mailbox&quot;">​</a></h1><p><a href="https://jmap.io" target="_blank" rel="noreferrer">JMAP</a> is a modern, HTTP-based replacement for IMAP. Fastmail offers it, as do servers built on <a href="https://stalw.art" target="_blank" rel="noreferrer">Stalwart</a>, Cyrus IMAP and Apache James. A JMAP source archives one mailbox, like a <a href="./imap.html">Generic IMAP</a> source, but asks the server only for what changed since the last sync instead of scanning every folder.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li><strong>Server URL:</strong> the address of the JMAP server. Open Archiver reads the server&#39;s settings from <code>/.well-known/jmap</code> under that address.</li><li><strong>Username:</strong> the mailbox&#39;s email address.</li><li><strong>A credential</strong>, one of: <ul><li>an <strong>API token</strong>, sent as a Bearer token. Fastmail uses this.</li><li>a <strong>password</strong>, sent with HTTP Basic authentication. Use an app password where the server offers one, as Stalwart does, rather than the account&#39;s main password.</li></ul></li></ul><h3 id="fastmail" tabindex="-1">Fastmail <a class="header-anchor" href="#fastmail" aria-label="Permalink to &quot;Fastmail&quot;">​</a></h3><ol><li>In Fastmail, go to <strong>Settings → Privacy &amp; Security → Manage API tokens</strong> and create a new token.</li><li>Give it read access to <strong>Mail</strong>. Open Archiver never writes to the mailbox.</li><li>Copy the token; Fastmail shows it only once.</li></ol><p>Use the server URL <code>https://api.fastmail.com</code>, your Fastmail address as the username, and <strong>API token</strong> as the authentication.</p><h3 id="stalwart" tabindex="-1">Stalwart <a class="header-anchor" href="#stalwart" aria-label="Permalink to &quot;Stalwart&quot;">​</a></h3><ol><li>Sign in to Stalwart&#39;s self-service portal and open <strong>App Passwords</strong>.</li><li>Create one for Open Archiver and copy it.</li></ol><p>Use your Stalwart server&#39;s address (for example <code>https://mail.example.com</code>) as the server URL, your email address as the username, and <strong>Password or app password</strong> as the authentication.</p><h2 id="step-by-step-guide" tabindex="-1">Step-by-Step Guide <a class="header-anchor" href="#step-by-step-guide" aria-label="Permalink to &quot;Step-by-Step Guide&quot;">​</a></h2><ol><li>From the main dashboard, go to the <strong>Ingestions</strong> page and click <strong>Create New</strong>.</li><li>Fill in the form: <ul><li><strong>Name:</strong> a name you will recognize, such as &quot;Fastmail (JMAP)&quot;.</li><li><strong>Provider:</strong> select <strong>JMAP</strong>.</li><li><strong>Server URL</strong>, <strong>Username</strong>, <strong>Authentication</strong> and the <strong>API token</strong> or <strong>Password</strong>, as described above.</li></ul></li><li>Click <strong>Save changes</strong>. Open Archiver connects to the server straight away and only saves the source if the connection works.</li></ol><h2 id="what-gets-archived" tabindex="-1">What gets archived <a class="header-anchor" href="#what-gets-archived" aria-label="Permalink to &quot;What gets archived&quot;">​</a></h2><p>The same folders as for IMAP. Mail in the <strong>Drafts</strong>, <strong>Junk</strong> and <strong>Trash</strong> mailboxes is left out by default; set <code>ARCHIVE_DRAFTS=true</code> or <code>ALL_INCLUSIVE_ARCHIVE=true</code> to include them (see <a href="./#what-gets-archived">What gets archived</a>). A message filed in several mailboxes is archived once, under the first mailbox, with the others recorded as tags.</p><h2 id="how-syncing-works" tabindex="-1">How syncing works <a class="header-anchor" href="#how-syncing-works" aria-label="Permalink to &quot;How syncing works&quot;">​</a></h2><p>The first sync lists and archives every message. After that, each sync asks the server for the messages created or changed since the previous sync, so a quiet mailbox costs a handful of requests. If the server no longer remembers that point (servers keep it for at least 30 days), Open Archiver lists the whole mailbox again and skips everything already archived.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>One mailbox per source. Add one source per mailbox you want to archive.</li><li>The server&#39;s TLS certificate must be trusted by the machine running Open Archiver. For a private certificate authority, point <code>NODE_EXTRA_CA_CERTS</code> at its certificate.</li><li>Signing in with OAuth is not supported yet; use an API token or app password.</li></ul>',18)]))}const u=a(o,[["render",i]]);export{m as __pageData,u as default};
